/// <summary>
/// WolfA 16.04.21
/// </summary>
class NDXUSCImportService extends SysOperationServiceBase
{
    SysGlobalobjectCache sgoc;
}

Method.Source:
public void new ()
{
    super();

    sgoc = new SysGlobalObjectCache();
}

/// <summary>
/// importUSC method
/// </summary>
/// <param name = "_NDXUSCImportContract">NDXUSCImportContract</param>
public void importUSC(NDXUSCImportContract _NDXUSCImportContract)
{
    NDXUSCCheck ndxUSCCheck;
    boolean isUSCImporting;
    [isUSCImporting] = sgoc.find(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey']);


    if (!isUSCImporting)
    {
        sgoc.insert(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey'], [true]);

        try
        {
            ndxUSCCheck = new NDXUSCCheck();

            if(_NDXUSCImportContract.parmAll())
            {
                ndxUSCCheck.run();
            }
            else
            {
                ndxUSCCheck.runSingle(_NDXUSCImportContract.parmTaxVATNumTable());
            }
            Info('USC Import Succesful');
        }
        catch
        {
            Info('USC Import Error');
        }
    }

    sgoc.remove(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey']);
}
